// OPGAVE 1.c: TEST HASH FUNCTIONS
//
// raportér kun køretider (for begge hash funktioner) og (fastholdt) n 
// dvs. resultatet (sum) er irrelevant

let Opgave1 n l = 
    let stream = generateStream n l
    // benchmarking MultiplyShift hashing
    let sw = Stopwatch()
    let h = hashShift a l
    let sum = Array.sumBy (fun (x,_) -> timer sw (fun _ -> h x)) stream
    let time = sw.Elapsed.TotalMilliseconds
    // benchmarking MultiplyModPrime hashing
    let sw' = Stopwatch()
    let h' = hashModPrime a' b' l
    let sum' = Array.sumBy (fun (x,_) -> timer sw' (fun _ -> h' x)) stream
    let time' = sw'.Elapsed.TotalMilliseconds
    // presentation
    printfn $"
    ===== Opgave 1 =====
    MultiplyShift runtime    : %.3f{time} ms
    MultiplyModPrime runtime : %.3f{time'} ms
        (sums : {sum} , {sum'})"

// OPGAVE 3: EXACT HASH TABLE EXPERIMENTS
//
// raportér køretider (for begge hash funktioner) og l (for fastholdt n)
// gem køretider og l til en csv, og præsentér i en tabel
// dvs. resultater (kvadratsum) er irrelevant

let Opgave3 n ls r =
    let arr = 
        ls
        |> Array.map (fun l -> 
            l, 
            generateStream n l, 
            HashTable(hashShift a, l), 
            HashTable(hashModPrime a' b', l))
        |> Array.map (fun (l, s, t, t') -> 
            l, 
            avg_runtime r (fun () -> squareSum s t), 
            avg_runtime r (fun () -> squareSum s t'))
        |> Array.map (fun (l, (t,s),(t',s')) -> 
            l, 
            (t, Array.sum s / bigint r), 
            (t', Array.sum s' / bigint r))
    // presentation
    printfn $"
    ===== Opgave 3 =====
    (l , SquareSum runtime (MulShift) , SquareSum runtime (MulModPrime))   (square sum (MulShift), square sum (MulModPrime))"
    for (l, (t,s),(t',s')) in arr do
        printfn $"     %-2d{l}  %9.3f{t}  %9.3f{t'}       ({s}, {s'})"

// OPGAVE 7 & 8: COUNT-SKETCH EXPERIMENTS
// 7:
// brug fastholdt l og n
// returnér RESULTATET (S = kvadratsum) med ExactExperiment
// returnér RESULTATET (X_i = kvadratsumsestimat) af 100 runs af CountSketch
// sørg for at de 100 iterationer af CountSketch bruger nye tilfældige bits
// gem kvadratsumsestimater til en csv og lav diverse plots af X_i og S
// 
// 8: 
// gentag de 100 runs (samme stream, l og n) med 2-3 forskellige værdier af m
// returnér både RESULTATER og KØRETIDER (gennemsnit) for forskellige m
// gem kvadratsumsestimater til en csv og lav diverse plots af X_i og S

let Opgave7'8 (n : int) (l : int) (ts : int[]) =
    let stream = generateStream n l
    let S = squareSum stream (HashTable(hashShift a, l))

    let experiments_t (t : int) =
        let sw = Stopwatch()
        let results = Array.map (fun a' -> timer sw (fun () -> CountSketch t a' stream) |> estimateSquareSum) a0123
        let avg_time = sw.Elapsed.TotalMilliseconds / float (Array.length a0123)
        let medians =
            results
            |> Array.chunkBySize 11
            |> Array.filter (fun chunk -> chunk.Length = 11)
            |> Array.map (fun chunk -> (Array.sort chunk)[6])
            |> Array.sort
            |> Array.zip [|1..((Array.length a0123)/11)|]
        let mse = Array.sumBy (fun X -> (X-S)*(X-S)) results / bigint (Array.length a0123)
        let points = 
            results
            |> Array.sort
            |> Array.zip [|1..(Array.length a0123)|] 

        t, avg_time, mse, S, points, medians

    let exp_res = Array.map (fun t -> experiments_t t) ts
    // presentation
    printfn $"
    ===== Opgave 7 & 8 ====="
    for t, avg_time, mse, S, points, medians in exp_res do
        printfn $"m = 2^{t},   mean runtime = %.3f{avg_time},   MSE = {mse},   S = {S}"
        printfn "Medians = %A" medians
        printfn "Points = %A\n" points

    